function statusClass(s){return s==='Eligible'?'eligible':s==='Possibly Eligible'?'possible':'ineligible'}
function evaluateScheme(user, scheme){
  let score=100, reasons=[], blockers=[];
  const income=+user.income, loan=+user.loanAmount, cost=+user.projectCost;
  if(scheme.maximumLoan===0){ score-=0; reasons.push('This is a benefit scheme rather than a loan; loan amount is not applicable.'); }
  else if(loan<=scheme.maximumLoan){reasons.push(`Requested amount is within the displayed scheme/project limit of ${fmt(scheme.maximumLoan)}.`)}
  else {score-=35;blockers.push(`Requested amount exceeds the displayed limit of ${fmt(scheme.maximumLoan)}.`)}
  if(scheme.incomeLimit==null || income<=scheme.incomeLimit) reasons.push(scheme.incomeLimit?`Annual family income fits the displayed ceiling of ${fmt(scheme.incomeLimit)}.`:'No simple income ceiling is encoded; lender/scheme-specific checks still apply.');
  else {score-=30;blockers.push(`Annual family income is above the displayed ceiling of ${fmt(scheme.incomeLimit)}.`)}
  if(scheme.ageMin<=+user.age && +user.age<=scheme.ageMax) reasons.push('Age is within the broad profile range used by this matcher.'); else {score-=20;blockers.push('Age needs further verification against the official scheme rules.')}
  const purposeKey=user.purpose==='education'?'education':user.projectType;
  if(scheme.purposes.includes(purposeKey) || (user.purpose==='business'&&scheme.purposes.includes('micro')) || (user.projectType==='dairy'&&scheme.purposes.includes('agriculture'))) reasons.push('Your stated purpose/project is aligned with this scheme.'); else {score-=30;blockers.push('The stated purpose does not closely match the scheme profile.')}
  if(cost>0 && loan>0 && scheme.maximumLoan>0 && loan<=cost*1.15) reasons.push('Requested finance is proportionate to the stated project cost.'); else if(scheme.maximumLoan>0){score-=8;blockers.push('Requested finance looks high compared with project cost; review your estimate.')}
  const genderOk=scheme.genderEligibility.includes(user.gender); const categoryOk=scheme.categoryEligibility.includes(user.socialCategory); if(genderOk || categoryOk || !scheme.targetRule) reasons.push('Gender/social-category profile is compatible with the encoded scheme audience.'); else {score-=22;blockers.push('Gender or social-category eligibility may restrict this scheme; verify the official rule.')}
  if(scheme.maritalEligibility.includes(user.maritalStatus)) reasons.push('Marital-status profile is compatible with the encoded scheme audience.');
  if(scheme.states.includes('ALL')||scheme.states.includes(user.state)) reasons.push('State/location is covered by the displayed scheme footprint.'); else {score-=35;blockers.push(`This scheme is currently encoded for ${scheme.states.join(', ')}.`)}
  if(user.disability==='yes') reasons.push('Disability status is retained for future scheme-specific matching; verify any applicable reservation/support.');
  if(user.residence==='rural') reasons.push('Rural residence may be relevant for certain agriculture/rural livelihood schemes.');
  if(user.existingLoan==='yes') reasons.push('Existing loan obligations should be disclosed to the lender; repayment capacity may affect sanction.');
  score=Math.max(8,Math.min(99,score));
  const hard=blockers.filter(x=>/exceeds|above|does not|encoded for/.test(x)).length;
  const status=hard>=2?'Not Eligible':score>=78?'Eligible':score>=52?'Possibly Eligible':'Not Eligible';
  return {...scheme,score,status,reasons,blockers};
}
function recommendations(){return schemes.map(s=>evaluateScheme(APP.user,s)).sort((a,b)=>b.score-a.score)}
function partnerRanking(schemeId){
  return partners.map(p=>{
    const compatible=p.schemes.includes(schemeId), eligible=p.operational && !p.npaRestriction && p.fund!=='Paused' && p.fund!=='Temporarily paused';
    let score=(compatible?60:0)+(eligible?30:0)+Math.max(0,10-p.distance);
    if(!p.operational) score-=45;if(p.npaRestriction)score-=18;if(!compatible)score-=35;
    return {...p,compatible,eligible,routeScore:score};
  }).sort((a,b)=>b.routeScore-a.routeScore);
}
function emiCalc(amount, annualRate, months, moratorium){
  amount=+amount; annualRate=+annualRate; months=+months; moratorium=+moratorium;
  const r=annualRate/12/100; const repayMonths=Math.max(1,months-moratorium);
  const moratoriumInterest=amount*r*moratorium; const financed=amount+moratoriumInterest;
  const emi=r===0?financed/repayMonths:financed*r*Math.pow(1+r,repayMonths)/(Math.pow(1+r,repayMonths)-1);
  const total=emi*repayMonths, interest=total-amount;
  return {emi,total,interest,principal:amount,repayMonths,moratorium,moratoriumInterest};
}
